export const content = '--- [Arquivo: estatistica.txt] ---\nA média aritmética é a soma dos valores dividida pela quantidade. A mediana é o valor central dos dados ordenados. Valores extremos afetam a média.\n--- [Arquivo: aplicacoes.txt] ---\nA escolha entre média e mediana depende do objetivo. Para descrever salário típico com valores extremos, a mediana pode ser mais representativa. Em produção, a média preserva a relação com o total.';
export const sources = [{id:'s1',name:'estatistica.txt'},{id:'s2',name:'aplicacoes.txt'}];
export const outline = {title:'Estatística para tomar decisões',description:'Entenda o que cada medida revela e aprenda a escolher uma interpretação para dados reais.',goals:['Calcular e interpretar a média','Escolher medidas adequadas à pergunta'],prerequisites:['Operações básicas'],coverage:[{id:'t1',sourceId:'s1',title:'Média e valores extremos'},{id:'t2',sourceId:'s2',title:'Escolha de uma medida'}],chapters:[{id:'c1',title:'Quando a média conta uma história incompleta',objective:'Calcular a média e avaliar o efeito de valores extremos.',topicIds:['t1','t2'],sourceIds:['s1','s2']},{id:'c2',title:'Mediana e decisões',objective:'Comparar medidas e justificar decisões.',topicIds:['t1','t2'],sourceIds:['s1','s2']}]};
export const question = {prompt:'Uma empresa divulga salário médio de R$ 4.120, mas quatro de seus cinco funcionários recebem menos de R$ 2.400. Qual conclusão é sustentada?',options:['A média está necessariamente errada.','Um salário alto pode elevar a média, sem representar o salário típico.','Todos recebem aproximadamente R$ 4.120.','A média ignora o maior salário.'],correct:1,rationales:['A conta pode estar correta; o problema é a interpretação.','Correto: a média considera a soma, que pode ser elevada por um valor extremo.','A média não garante proximidade entre os valores individuais.','A média inclui todos os valores, inclusive o maior.'],hint:'Compare o que acontece com a soma quando só o maior salário aumenta.',skill:'Interpretar o efeito de valores extremos'};
const makeBeat = (focus,caption,narration) => ({focus,caption,narration});
const scene = (title,role,kind,items,beats,checkpoint=null) => ({title,role,topicIds:['t1','t2'],sourceIds:['s1','s2'],visual:{kind,items},beats,checkpoint});
const item=(id,label,detail='',value)=>({id,label,detail,...(value===undefined?{}:{value})});
export const chapter = {id:'c1',title:outline.chapters[0].title,estimatedMinutes:7,scenes:[
scene('Cinco salários, duas histórias','concept','bars',[
item('a','R$ 2.000','Pessoa A',2000),item('b','R$ 2.100','Pessoa B',2100),item('c','R$ 2.200','Pessoa C',2200),item('d','R$ 2.300','Pessoa D',2300),item('e','R$ 12.000','Pessoa E',12000)], [
makeBeat(['a','b'],'Comece olhando os dados individuais.','Vamos usar um exemplo hipotético de cinco salários para investigar uma pergunta concreta: quanto recebe uma pessoa típica desta empresa? As duas primeiras barras representam dois mil e dois mil e cem reais. Elas têm alturas parecidas porque os valores são próximos. Antes de calcular qualquer coisa, observar a distribuição ajuda a entender o problema.'),
makeBeat(['c','d'],'Quatro salários estão próximos entre si.','Agora aparecem os outros dois salários menores, de dois mil e duzentos e dois mil e trezentos reais. Temos quatro pessoas em uma faixa relativamente estreita. Essa concentração importa: se alguém nos perguntar sobre a situação da maioria, esperamos que a resposta tenha alguma relação com esse grupo, sem apagar as diferenças entre as pessoas.'),
makeBeat(['e'],'O maior salário altera o equilíbrio do conjunto.','A última barra representa doze mil reais. Ela é muito mais alta, mas continua sendo apenas uma das cinco observações. É um valor extremo em relação aos demais. Não podemos removê-lo só porque incomoda; primeiro precisamos entender sua influência no cálculo e escolher a medida que responde melhor à pergunta que estamos fazendo.')]),
scene('Construindo a média, operação por operação','worked-example','equation',[
item('a','2.000 + 2.100 + 2.200 + 2.300 + 12.000','Somar todos os salários'),item('b','20.600 ÷ 5','Dividir pela quantidade de pessoas'),item('c','Média = R$ 4.120','Uma divisão igual do total')],[
makeBeat(['a'],'Passo 1 · reunir o total.','Para calcular a média aritmética, começamos somando os cinco salários. O resultado é vinte mil e seiscentos reais. Perceba que a soma considera tanto os quatro salários menores quanto o maior. A média não ignora diferenças; ela as reúne em um total, que será repartido matematicamente no próximo passo da resolução.'),
makeBeat(['b'],'Passo 2 · dividir por cinco observações.','Temos cinco pessoas, portanto dividimos o total por cinco. Não dividimos pela quantidade de salários diferentes nem pelo número de salários próximos entre si. O denominador é a quantidade de observações. Essa distinção evita um erro comum: escolher uma quantidade conveniente e produzir um resultado que já não corresponde à média de todo o grupo.'),
makeBeat(['c'],'Passo 3 · interpretar o resultado, além de calcular.','A divisão resulta em quatro mil e cento e vinte reais. Esse seria o salário de cada pessoa se distribuíssemos o total igualmente entre as cinco. Não significa que alguém recebe exatamente esse valor. A interpretação da média como repartição igual do total é correta; tratá-la como o salário de todos seria uma conclusão indevida.')]),
scene('Conta correta não garante interpretação correta','concept','comparison',[
item('a','Média: R$ 4.120','Preserva a relação com a soma'),item('b','Quatro abaixo de R$ 2.400','Mostra a concentração dos valores'),item('c','Pergunta: salário típico?','Exige avaliar a distribuição')],[
makeBeat(['a'],'A média responde a uma pergunta sobre o total.','Se a empresa precisa estimar o gasto total com esse mesmo grupo, a média é útil. Multiplicar quatro mil e cento e vinte por cinco recupera os vinte mil e seiscentos reais. Existe, portanto, uma informação importante nessa medida. O problema não está em sua existência, mas em utilizá-la para responder qualquer pergunta sem considerar o contexto.'),
makeBeat(['b'],'A maioria pode ficar bem abaixo da média.','Quatro das cinco pessoas recebem menos de dois mil e quatrocentos reais. Apesar disso, a média supera quatro mil. Esse contraste não é uma contradição matemática. O salário mais alto pesa na soma e puxa a média para cima. Quanto mais ele aumentar, mantendo os outros salários iguais, maior será a distância entre a média e esse grupo.'),
makeBeat(['c'],'Antes de escolher a medida, defina a pergunta.','Agora precisamos separar duas perguntas: qual valor por pessoa reproduz o total e qual valor descreve melhor a posição central das pessoas? A média responde diretamente à primeira. A segunda pede observar a ordem dos salários e pode nos levar à mediana. A escolha de uma medida deve ser justificada pela pergunta, não por parecer mais favorável.')],question),
scene('Da pergunta à decisão','application','process',[
item('a','Defina o objetivo','Custo total ou situação típica?'),item('b','Inspecione a distribuição','Há valores extremos?'),item('c','Escolha e justifique','Média, mediana ou ambas')],[
makeBeat(['a'],'Primeiro: qual decisão será tomada?','Imagine que você trabalha na administração e precisa preparar um relatório. Se o objetivo é estimar o orçamento necessário para manter essa equipe, a relação da média com o total é relevante. Se o objetivo é comunicar a situação salarial da maioria, o mesmo número pode esconder diferenças importantes. Escreva a pergunta antes de escolher o indicador.'),
makeBeat(['b'],'Segundo: verifique o que o indicador pode esconder.','Observe quantos valores estão próximos e quais ficam distantes. Uma tabela ou um gráfico simples já pode mostrar a concentração. Essa inspeção não substitui o cálculo, mas orienta sua interpretação. No nosso exemplo, a diferença entre o maior salário e os demais indica que um único número talvez não descreva satisfatoriamente toda a distribuição.'),
makeBeat(['c'],'Terceiro: comunique a medida junto com seu limite.','Uma resposta bem fundamentada pode apresentar média e mediana, explicando o que cada uma informa. Não precisamos declarar uma medida sempre superior à outra. Precisamos tornar claro por que ela foi usada, quais valores entraram na conta e quais diferenças podem ficar escondidas. Essa justificativa transforma uma conta correta em uma análise útil para a decisão.')]),
scene('Uma nova situação: produção diária','worked-example','equation',[
item('a','4 + 6 + 8 + 10 = 28','Exemplo hipotético: quatro dias'),item('b','28 ÷ 4 = 7','Produção média diária'),item('c','7 × 4 = 28','Verificação pelo total')],[
makeBeat(['a'],'Transfira o raciocínio para um novo contexto.','Vamos testar a mesma ideia com um exemplo hipotético de produção: quatro, seis, oito e dez peças em quatro dias. Somamos os valores e obtemos vinte e oito peças. O contexto mudou, mas a definição permanece a mesma. Cada dia é uma observação, e queremos um valor diário que preserve a relação com o total produzido.'),
makeBeat(['b'],'Calcule e mantenha a unidade correta.','Dividimos vinte e oito peças por quatro dias e obtemos sete peças por dia. Aqui a unidade ajuda a interpretar a conta: o resultado é uma produção média diária. Nenhum dos dias precisa ter produzido sete peças para que a média seja válida. Ela representa uma distribuição uniforme do total ao longo do período observado.'),
makeBeat(['c'],'Verifique o cálculo e explique seu alcance.','Multiplicar sete por quatro recupera vinte e oito, confirmando a relação entre média, quantidade e soma. Mas a média sozinha não informa a oscilação entre os dias. Para planejar capacidade ou investigar atrasos, talvez precisemos olhar também os valores individuais. Na atividade seguinte, você vai escolher um indicador e defender sua interpretação com esse cuidado.')],question)
],practice:{scenario:'Você prepara um relatório sobre a empresa do exemplo. A diretoria quer divulgar que o salário típico é R$ 4.120.',prompt:'Escreva uma recomendação de 4 a 6 frases: avalie essa interpretação, justifique com os dados e proponha uma comunicação mais adequada.',criteria:['Distingue média de salário típico','Explica o efeito do maior salário','Usa pelo menos um valor para sustentar a análise','Propõe uma comunicação que não esconda diferenças'],modelAnswer:'A média de R$ 4.120 está matematicamente correta, pois a soma dos cinco salários é R$ 20.600. Entretanto, quatro pessoas recebem menos de R$ 2.400, e o salário de R$ 12.000 eleva a média. Para comunicar a situação típica, eu apresentaria também a mediana de R$ 2.200 e a distribuição dos valores. Assim, o relatório mostra o custo médio sem sugerir que a maioria recebe esse valor.'},quiz:Array.from({length:4},()=>structuredClone(question))};
export function courseFixture() { return {kind:'course',version:2,id:'test-course',title:outline.title,sourceText:content,youtubeUrls:[],outline:structuredClone(outline),sources:structuredClone(sources),chapters:{c1:structuredClone(chapter)},progress:{}}; }
